<?php require_once dirname(__DIR__).'/config.php';require_once TBK_ROOT.'/includes/helpers.php';$items=tbk_tools();$cats=tbk_categories();$canonical=tbk_url('tools/');$head_callback=function()use($canonical){tbk_page_head('All Online Tools','Browse every free ToolboxKart utility by category.',$canonical);};require TBK_ROOT.'/partials/header.php';?><section class="directory-head"><div class="wrap"><h1>All tools</h1><p>Search or browse the complete ToolboxKart directory.</p><div class="tool-search" style="margin-left:0"><input data-tool-search placeholder="Search all tools…"><button type="button">Search</button></div><div class="search-results" data-search-results style="margin-left:0"></div></div></section><section class="section"><div class="wrap"><div class="tool-grid"><?php foreach($items as $t):$c=$cats[$t['category']];?><a class="tool-card" href="/<?=e($t['category'])?>/<?=e($t['slug'])?>/"><span class="tool-kicker"><?=e($c['name'])?></span><h3><?=e($t['name'])?></h3><p><?=e($t['description'])?></p><span class="arrow">Open tool →</span></a><?php endforeach;?></div></div></section><script>window.TBK_INDEX=<?=json_encode(array_map(fn($t)=>['name'=>$t['name'],'category'=>$cats[$t['category']]['name'],'desc'=>$t['description'],'url'=>'/'.$t['category'].'/'.$t['slug'].'/'],$items),JSON_UNESCAPED_SLASHES)?>;</script><?php require TBK_ROOT.'/partials/footer.php';?>